Задача — store.go:
  type Store struct{ pool *pgxpool.Pool }
  func NewStore(pool *pgxpool.Pool) *Store
  func ListReceipts(ctx, chatID int64, limit, offset int) ([]ReceiptSummary, error)
    SQL: SELECT r.id, COALESCE(st.name,''), COALESCE(r.purchase_ts,NOW()), COALESCE(r.total_amount,0), COALESCE(r.currency,'RUB'), COUNT(ri.id)
    FROM receipt r LEFT JOIN store st ON st.id=r.store_id LEFT JOIN receipt_item ri ON ri.receipt_id=r.id
    WHERE r.chat_id= GROUP BY r.id,st.name ORDER BY r.purchase_ts DESC NULLS LAST LIMIT  OFFSET 
