    SQL: SELECT COALESCE(c.name,'Другое'), SUM(ri.amount), COUNT(ri.id)
    FROM receipt r JOIN receipt_item ri ON ri.receipt_id=r.id LEFT JOIN category c ON c.id=ri.category_id
    WHERE r.chat_id= AND r.purchase_ts>= AND r.purchase_ts< GROUP BY c.name ORDER BY SUM(ri.amount) DESC
  func GetReceipt(ctx, id uuid.UUID) (*ReceiptDetail, error)
    SQL: два запроса — receipt JOIN store + receipt_item JOIN category
